
use super::*;
use std::fmt::Write as _;
use crate::{lint::{Lint,Cx,RuleMeta,ScanKind,Site},tree::{Tree,SourceFile,Select}};
#[path="policy_finish_original.rs"]mod original;
#[path="policy_judge_original.rs"]mod original_judge;
#[path="../../dmb/shared/test_scratch.rs"]mod test_scratch;
struct Probe{meta:Meta}
impl Lint for Probe{
 fn meta(&self)->&Meta{&self.meta}
 fn finish_raw(&self,_:&Cx,run:&Run,out:&mut String,raw:bool)->bool{writeln!(out,"custom {} {raw}",run.sites.len()).unwrap();!run.sites.is_empty()}
 fn post_judge(&self,_:&Cx,_:&Run,out:&mut String)->bool{out.push_str("post\n");false}
}
fn probe(policy:Policy)->Probe{Probe{meta:Meta{name:"probe",group:"",label:"probe",legacy:"",select:Select::dm(&[("code/","dm")]),scan:ScanKind::File,policy,rules:&[RuleMeta{name:"first",hint:"use the native form"},RuleMeta{name:"second",hint:""},RuleMeta{name:"banned",hint:"removed"}],allow:&[],lists:&[]}}}
fn data()->(Tree,Run,Vec<AllowUse>){let tree=Tree::from_files(vec![SourceFile::from_text("code/a.dm","alpha()\nbeta()\n"),SourceFile::from_text("code/b.dm","gamma()\n")]);let run=Run{sites:vec![Site{rule:"first".into(),rel:"code/a.dm".into(),line:1,msg:String::new(),key:"A".into(),ident:String::new()},Site{rule:"second".into(),rel:"code/b.dm".into(),line:1,msg:"original message".into(),key:"B".into(),ident:"/datum/probe::charge".into()},Site{rule:"banned".into(),rel:"code/a.dm".into(),line:2,msg:String::new(),key:String::new(),ident:String::new()}],notes:vec!["original ordered note".into()]};let used=vec![AllowUse{rel:"code/a.dm".into(),line:1,name:"probe".into(),code:"KEPT".into()},AllowUse{rel:"code/a.dm".into(),line:1,name:"probe".into(),code:"OTHER".into()}];(tree,run,used)}
#[test]fn complete_common_finish_preserves_original_judgement_outcomes_render_order_and_all_allow_rows(){
 let(tree,run,used)=data();let root=test_scratch::dir("policy-finish-complete");std::fs::create_dir_all(root.join("tools/ci")).unwrap();std::fs::write(root.join("tools/ci/probe.txt"),"first\tcode/a.dm\talpha()\n").unwrap();
 for policy in[Policy::Hard,Policy::Sites{baseline:"tools/ci/probe.txt",header:&["# original"],banned:&["banned"]},Policy::Ceilings{baseline:"tools/ci/counts.txt",header:&["# counts"]},Policy::Custom]{for raw in[false,true]{for changed in[None,Some(["code/b.dm".to_owned()].into_iter().collect())]{let lint=probe(policy);let mut scope=LintScope::default();scope.ceilings.insert("first".into(),0);let cx=Cx{ fixture:None,tree:&tree,meta:&lint.meta,scope:&scope};let expected=original_judge::judge(&lint,&cx,&run,&root,&changed,raw);let out=finish_report(&lint.meta,&scope,&tree,run.clone(),used.clone(),Timing::default(),&root,&changed,raw,|run,out,raw|lint.finish_raw(&cx,run,out,raw),|run,out|lint.post_judge(&cx,run,out));assert_eq!((out.failed,&out.text),(expected.0,&expected.1));assert_eq!(out.run.sites,run.sites);assert_eq!(out.run.notes,run.notes);assert_eq!(out.allow_used,used);assert!(out.internal_error.is_none());let outcomes=[out];for ci in[false,true]{assert_eq!(render(&outcomes,ci),original::render(&outcomes,ci));}}}}
}
#[test]fn whole_original_baseline_modes_preserve_all_files_ceilings_identity_bans_and_custom_results(){
 let(tree,run,_)=data();for policy in[Policy::Hard,Policy::Sites{baseline:"tools/ci/probe.txt",header:&["# original"],banned:&["banned"]},Policy::Ceilings{baseline:"tools/ci/counts.txt",header:&["# counts"]},Policy::Custom]{for mode in[Mode::Seed,Mode::Update,Mode::Migrate]{let old=test_scratch::dir("policy-baseline-old");let new=test_scratch::dir("policy-baseline-native");for root in[&old,&new]{std::fs::create_dir_all(root.join("tools/ci")).unwrap();std::fs::write(root.join("tools/ci/probe.txt"),"first\tcode/a.dm\talpha()\nsecond\tcode/b.dm\tgamma()\nsecond\tcode/c.dm\tunclaimed old spelling\n").unwrap();std::fs::write(root.join("tools/ci/counts.txt"),"A 4\nB 2\n").unwrap();std::fs::write(root.join("tools/ci/lint_scopes.toml"),"# retained comment\n[lint.probe.ceilings]\nfirst=5\n").unwrap();}let lint=probe(policy);let mut scope=LintScope::default();scope.ceilings.insert("first".into(),5);let old_text=original::update(&lint.meta,&scope,&tree,&run,&old,&old,mode,|run,mode|Ok(format!("custom {} {mode:?}",run.sites.len()))).unwrap();let new_text=update_baseline_report(&lint.meta,&scope,&tree,&run,&new,&new,mode,|run,mode|Ok(format!("custom {} {mode:?}",run.sites.len()))).unwrap();assert_eq!(new_text,old_text);for name in["probe.txt","counts.txt","lint_scopes.toml"]{assert_eq!(std::fs::read(new.join("tools/ci").join(name)).unwrap(),std::fs::read(old.join("tools/ci").join(name)).unwrap(),"{name} {mode:?}");}}}
}
#[test]fn common_allow_usage_requires_explicit_as_of_digests_and_preserves_original_ordered_dedup(){
 let(tree,run,mut used)=data();used.push(AllowUse{rel:"code/b.dm".into(),line:3,name:"other".into(),code:String::new()});let lint=probe(Policy::Hard);let scope=LintScope::default();let output=finish_report(&lint.meta,&scope,&tree,run,used,Timing::default(),Path::new("."),&None,true,|_,_,_|panic!("hard policy has no custom finish"),|_,_|false);let mut calls=0;let rows=allow_usage_rows::<std::io::Error>(&[output],|relative|{calls+=1;Ok(if relative=="code/a.dm"{AllowFileDigest::Captured("actual-issued-sha1")}else{AllowFileDigest::ProvenMissing})}).unwrap();assert_eq!(calls,2);let mut bytes=Vec::new();write_allow_rows(&rows,&mut bytes).unwrap();assert_eq!(bytes,b"other\t\t3\nprobe\tactual-issued-sha1\t1\n");
 let(_,run,used)=data();let output=finish_report(&lint.meta,&scope,&tree,run,used,Timing::default(),Path::new("."),&None,true,|_,_,_|false,|_,_|false);let error=allow_usage_rows(&[output],|_|Err::<AllowFileDigest<'static>,_>(std::io::Error::from_raw_os_error(1450))).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450),"missing/failed digest provider is never an empty-file digest");
}
#[test]fn common_finish_frozen_original_runner_and_projection_are_exact(){
 use sha1::Digest as _;let bytes=include_bytes!("policy_finish_original.reference");let actual:[u8;20]=sha1::Sha1::digest(bytes).into();assert_eq!(actual,[95,128,66,22,65,220,166,93,247,56,22,52,23,116,110,170,63,28,198,33]);
 let old=std::str::from_utf8(bytes).unwrap();let begin=old.find("/// Prints outcomes").unwrap();let end=old[begin..].find("pub fn meta_of").unwrap()+begin;let render=&old[begin..end];assert!(include_str!("policy_finish_original.rs").contains(render));
 let begin=old.find("    pub fn update_baseline(").unwrap();let end=old[begin..].find("\n    }").unwrap()+begin+6;let method=&old[begin..end];let core=&method[method.find("        let by_rule =").unwrap()..];let projected=core.replace("let scopes_root = self.opts.scopes_from.clone().unwrap_or_else(|| self.opts.root.clone());","let scopes_root = scopes_root.to_path_buf();").replace("self.baseline_path(baseline)","root.join(baseline)").replace("&self.tree","source").replace("lint.update_baseline(&cx, &run, mode)","custom(run, mode)");assert!(include_str!("policy_finish_original.rs").contains(&projected),"entire old baseline algorithm must be present with only nominal source/context transport");
}

#[test]fn common_allow_usage_complete_original_file_digest_and_projection_match_without_source_reread(){
 use sha1::Digest as _;let original=include_str!("policy_finish_allow_original.reference");let hash:[u8;20]=sha1::Sha1::digest(original.as_bytes()).into();assert_eq!(hash,[182,99,238,6,231,210,244,123,90,2,179,113,158,255,0,141,145,205,90,115]);
 let start=original.find("    let mut rows:").unwrap();let end=original.find("    if let Ok(mut f)").unwrap();let body=original[start..end].replace("engine.tree.get","tree.get");assert!(include_str!("policy_finish_original.rs").contains(&body));
 let(tree,run,used)=data();let lint=probe(Policy::Hard);let out=finish_report(&lint.meta,&LintScope::default(),&tree,run,used,Timing::default(),Path::new("."),&None,true,|_,_,_|false,|_,_|false);let outcomes=[out];let old=original::original_allow_usage(&tree,&outcomes);
 // These are already-delivered digest strings; the formatter never receives
 // mutable source/Tree, nor a path from which to reconstruct one.
 let mut evidence=HashMap::new();for used in &outcomes[0].allow_used{let file=tree.get(&used.rel).unwrap();let mut digest=sha1::Sha1::new();digest.update(file.text().trim_end_matches('\n').as_bytes());let value=digest.finalize().iter().map(|b|format!("{b:02x}")).collect::<String>();evidence.insert(used.rel.clone(),value);}
 let actual=allow_usage_rows::<()>(&outcomes,|relative|Ok(AllowFileDigest::Captured(evidence.get(relative).ok_or(())?))).unwrap();assert_eq!(actual,old);let mut expected=Vec::new();for(name,digest,line)in old{use std::io::Write as _;writeln!(&mut expected,"{name}\t{digest}\t{line}").unwrap();}let mut actual_bytes=Vec::new();write_allow_rows(&actual,&mut actual_bytes).unwrap();assert_eq!(actual_bytes,expected);
}
